import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// ConvTranspose3d specialized for:
//   kernel = 3x3x3, stride = 1, padding = 0, output_padding = 0,
//   dilation = 1, groups = 1, dtype = float32
//   in  : (N, 48, 96, 96, 96)  contiguous
//   w   : (48, 24, 3, 3, 3)    contiguous  (in_ch, out_ch, kD, kH, kW)
//   bias: (24,) or dummy
//   out : (N, 24, 98, 98, 98)  contiguous
// out[b,oc,z,y,x] = sum_{ic,kz,ky,kx} w[ic,oc,2-kz,2-ky,2-kx]
//                   * in[b,ic,z+kz-2,y+ky-2,x+kx-2]   (zero outside input)
//                 + bias[oc] (optional)
//
// Structural rewrite: CTA-level output-row tiling with cooperative shared-memory
// input-row staging.  Each CTA owns one (b,z,y) output row (98 x-sites); the
// first 98 threads keep all 24 output-channel accumulators for one x-site, while
// all 128 threads cooperatively stage the three reusable input rows for the
// current (ic,kz) into shared memory before the tap loops run.
.visible .entry conv_transpose3d_k3_s1(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 total,
    .param .u32 has_bias
)
{
    .shared .align 16 .f32 wtile[648];
    .shared .align 16 .f32 inrow[288];
    .reg .pred  %p<12>;
    .reg .b32   %r<48>;
    .reg .b64   %rd<24>;
    .reg .f32   %f<32>;
    ld.param.u64 %rd0, [in_ptr];
    ld.param.u64 %rd1, [w_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.u32 %r0,  [total];
    ld.param.u32 %r1,  [has_bias];
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mov.u32 %r5, %r2;                       // row index = flattened (b,z,y)
    setp.ge.u32 %p0, %r5, %r0;              // uniform CTA guard
    @%p0 bra DONE;
    // decode row -> b(r10), z(r12), y(r13); x(r14) = clamped tid
    rem.u32 %r13, %r5, 98;
    div.u32 %r6,  %r5, 98;
    rem.u32 %r12, %r6, 98;
    div.u32 %r10, %r6, 98;
    min.u32 %r14, %r4, 97;                  // inactive lanes compute dummy x=97
    setp.lt.u32 %p6, %r4, 98;               // active output-column lane
    // tap bounds: klo = max(0, 2 - coord), khi = min(2, 97 - coord)
    mov.s32 %r15, 2;
    sub.s32 %r15, %r15, %r12;
    max.s32 %r15, %r15, 0;                  // kz_lo
    mov.s32 %r16, 97;
    sub.s32 %r16, %r16, %r12;
    min.s32 %r16, %r16, 2;                  // kz_hi
    mov.s32 %r17, 2;
    sub.s32 %r17, %r17, %r13;
    max.s32 %r17, %r17, 0;                  // ky_lo
    mov.s32 %r18, 97;
    sub.s32 %r18, %r18, %r13;
    min.s32 %r18, %r18, 2;                  // ky_hi
    mov.s32 %r19, 2;
    sub.s32 %r19, %r19, %r14;
    max.s32 %r19, %r19, 0;                  // kx_lo
    mov.s32 %r20, 97;
    sub.s32 %r20, %r20, %r14;
    min.s32 %r20, %r20, 2;                  // kx_hi
    // shared-memory base addresses in 32-bit space
    mov.u32 %r35, wtile;
    mov.u32 %r40, inrow;
    // 24 output-channel accumulators f0..f23
    mov.f32 %f0,  0f00000000;
    mov.f32 %f1,  0f00000000;
    mov.f32 %f2,  0f00000000;
    mov.f32 %f3,  0f00000000;
    mov.f32 %f4,  0f00000000;
    mov.f32 %f5,  0f00000000;
    mov.f32 %f6,  0f00000000;
    mov.f32 %f7,  0f00000000;
    mov.f32 %f8,  0f00000000;
    mov.f32 %f9,  0f00000000;
    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.f32 %f12, 0f00000000;
    mov.f32 %f13, 0f00000000;
    mov.f32 %f14, 0f00000000;
    mov.f32 %f15, 0f00000000;
    mov.f32 %f16, 0f00000000;
    mov.f32 %f17, 0f00000000;
    mov.f32 %f18, 0f00000000;
    mov.f32 %f19, 0f00000000;
    mov.f32 %f20, 0f00000000;
    mov.f32 %f21, 0f00000000;
    mov.f32 %f22, 0f00000000;
    mov.f32 %f23, 0f00000000;
    mov.u32 %r21, 0;                        // ic = 0
IC_LOOP:
    setp.ge.u32 %p1, %r21, 48;
    @%p1 bra IC_DONE;
    // rd4 = in + (b*48 + ic) * 884736 * 4   (input plane base)
    mad.lo.u32 %r22, %r10, 48, %r21;
    mul.lo.u32 %r22, %r22, 884736;
    mul.wide.u32 %rd5, %r22, 4;
    add.s64 %rd4, %rd0, %rd5;
    // rd6 = w + ic * 24 * 27 * 4 = w + ic*2592  (weight base for this ic)
    mul.lo.u32 %r23, %r21, 2592;
    cvt.u64.u32 %rd7, %r23;
    add.s64 %rd6, %rd1, %rd7;
    // Cooperatively stage this input channel's 27x24 weights in shared
    // memory, transposed to tap-major/oc-contiguous for v4 loads.
    mov.u32 %r36, %r4;
W_LOAD_LOOP:
    setp.ge.u32 %p2, %r36, 648;
    @%p2 bra W_LOAD_DONE;
    rem.u32 %r37, %r36, 27;               // tap
    div.u32 %r38, %r36, 27;               // oc
    mul.wide.u32 %rd18, %r36, 4;
    add.s64 %rd19, %rd6, %rd18;
    ld.global.f32 %f25, [%rd19];
    mad.lo.u32 %r39, %r37, 24, %r38;      // tap*24 + oc
    mul.lo.u32 %r39, %r39, 4;
    add.u32 %r39, %r35, %r39;
    st.shared.f32 [%r39], %f25;
    add.u32 %r36, %r36, %r3;
    bra W_LOAD_LOOP;
W_LOAD_DONE:
    bar.sync 0;
    mov.s32 %r24, %r15;                     // kz = kz_lo
KZ_LOOP:
    setp.gt.s32 %p3, %r24, %r16;
    @%p3 bra KZ_DONE;
    add.s32 %r25, %r12, %r24;
    sub.s32 %r25, %r25, 2;                  // iz = z + kz - 2 (valid by bounds)
    mul.lo.u32 %r26, %r25, 36864;           // iz * 96 * 96 * 4 (bytes)
    cvt.u64.u32 %rd8, %r26;
    add.s64 %rd9, %rd4, %rd8;               // input slice base
    // Stage all three candidate input rows for this (ic,kz): inrow[ky][ix].
    // Invalid edge rows are filled with zero and are never consumed.
    mov.u32 %r27, 0;                        // ky = 0
ROW_STAGE_LOOP:
    setp.ge.u32 %p4, %r27, 3;
    @%p4 bra ROW_STAGE_DONE;
    add.s32 %r28, %r13, %r27;
    sub.s32 %r28, %r28, 2;                  // iy = y + ky - 2
    setp.ge.s32 %p7, %r28, 0;
    setp.lt.s32 %p8, %r28, 96;
    and.pred %p9, %p7, %p8;                   // valid input row
    mul.lo.u32 %r29, %r28, 384;             // iy * 96 * 4 (bytes)
    cvt.u64.u32 %rd10, %r29;
    add.s64 %rd11, %rd9, %rd10;             // row base (only dereferenced if valid)
    setp.lt.u32 %p10, %r4, 96;              // this lane stages column tid
    mul.lo.u32 %r30, %r27, 96;
    add.u32 %r30, %r30, %r4;                // inrow linear element ky*96 + tid
    mul.lo.u32 %r30, %r30, 4;
    add.u32 %r41, %r40, %r30;               // shared destination
    mul.wide.u32 %rd12, %r4, 4;
    add.s64 %rd13, %rd11, %rd12;            // global source
    mov.f32 %f29, 0f00000000;
    and.pred %p11, %p9, %p10;
    @%p11 ld.global.f32 %f29, [%rd13];
    @%p10 st.shared.f32 [%r41], %f29;
    add.u32 %r27, %r27, 1;
    bra ROW_STAGE_LOOP;
ROW_STAGE_DONE:
    bar.sync 0;
    mov.s32 %r27, %r17;                     // ky = ky_lo
KY_LOOP:
    setp.gt.s32 %p5, %r27, %r18;
    @%p5 bra KY_DONE;
    // shared input base for this lane: inrow + (ky*96 + x + kx_lo - 2)*4
    mul.lo.u32 %r29, %r27, 96;
    add.s32 %r29, %r29, %r14;
    add.s32 %r29, %r29, %r19;
    sub.s32 %r29, %r29, 2;
    mul.lo.u32 %r29, %r29, 4;
    add.u32 %r42, %r40, %r29;
    // packed shared-memory weight tap: t = 26 - (kz*9 + ky*3 + kx_lo)
    mul.lo.u32 %r30, %r24, 9;
    mad.lo.u32 %r30, %r27, 3, %r30;
    add.s32 %r30, %r30, %r19;
    mov.u32 %r32, 26;
    sub.s32 %r30, %r32, %r30;
    mul.lo.u32 %r30, %r30, 96;              // tap stride = 24 oc * 4 B
    add.u32 %r36, %r35, %r30;               // packed weight tap pointer
    mov.s32 %r31, %r19;                     // kx = kx_lo
KX_LOOP:
    setp.gt.s32 %p7, %r31, %r20;
    @%p7 bra KX_DONE;
    ld.shared.f32 %f24, [%r42];             // staged input reused for all 24 oc
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36];
    fma.rn.f32 %f0,  %f24, %f25, %f0;
    fma.rn.f32 %f1,  %f24, %f26, %f1;
    fma.rn.f32 %f2,  %f24, %f27, %f2;
    fma.rn.f32 %f3,  %f24, %f28, %f3;
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36+16];
    fma.rn.f32 %f4,  %f24, %f25, %f4;
    fma.rn.f32 %f5,  %f24, %f26, %f5;
    fma.rn.f32 %f6,  %f24, %f27, %f6;
    fma.rn.f32 %f7,  %f24, %f28, %f7;
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36+32];
    fma.rn.f32 %f8,  %f24, %f25, %f8;
    fma.rn.f32 %f9,  %f24, %f26, %f9;
    fma.rn.f32 %f10, %f24, %f27, %f10;
    fma.rn.f32 %f11, %f24, %f28, %f11;
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36+48];
    fma.rn.f32 %f12, %f24, %f25, %f12;
    fma.rn.f32 %f13, %f24, %f26, %f13;
    fma.rn.f32 %f14, %f24, %f27, %f14;
    fma.rn.f32 %f15, %f24, %f28, %f15;
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36+64];
    fma.rn.f32 %f16, %f24, %f25, %f16;
    fma.rn.f32 %f17, %f24, %f26, %f17;
    fma.rn.f32 %f18, %f24, %f27, %f18;
    fma.rn.f32 %f19, %f24, %f28, %f19;
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36+80];
    fma.rn.f32 %f20, %f24, %f25, %f20;
    fma.rn.f32 %f21, %f24, %f26, %f21;
    fma.rn.f32 %f22, %f24, %f27, %f22;
    fma.rn.f32 %f23, %f24, %f28, %f23;
    add.u32 %r42, %r42, 4;                  // next staged input column
    sub.u32 %r36, %r36, 96;                 // previous packed weight tap
    add.s32 %r31, %r31, 1;
    bra KX_LOOP;
KX_DONE:
    add.s32 %r27, %r27, 1;
    bra KY_LOOP;
KY_DONE:
    bar.sync 0;                             // inrow can be overwritten next kz
    add.s32 %r24, %r24, 1;
    bra KZ_LOOP;
KZ_DONE:
    add.s32 %r21, %r21, 1;
    bra IC_LOOP;
IC_DONE:
    @!%p6 bra DONE;                         // inactive lanes never store
    setp.eq.u32 %p5, %r1, 0;
    @%p5 bra STORE;
    ld.global.f32 %f25, [%rd2];
    add.f32 %f0,  %f0,  %f25;
    ld.global.f32 %f25, [%rd2+4];
    add.f32 %f1,  %f1,  %f25;
    ld.global.f32 %f25, [%rd2+8];
    add.f32 %f2,  %f2,  %f25;
    ld.global.f32 %f25, [%rd2+12];
    add.f32 %f3,  %f3,  %f25;
    ld.global.f32 %f25, [%rd2+16];
    add.f32 %f4,  %f4,  %f25;
    ld.global.f32 %f25, [%rd2+20];
    add.f32 %f5,  %f5,  %f25;
    ld.global.f32 %f25, [%rd2+24];
    add.f32 %f6,  %f6,  %f25;
    ld.global.f32 %f25, [%rd2+28];
    add.f32 %f7,  %f7,  %f25;
    ld.global.f32 %f25, [%rd2+32];
    add.f32 %f8,  %f8,  %f25;
    ld.global.f32 %f25, [%rd2+36];
    add.f32 %f9,  %f9,  %f25;
    ld.global.f32 %f25, [%rd2+40];
    add.f32 %f10, %f10, %f25;
    ld.global.f32 %f25, [%rd2+44];
    add.f32 %f11, %f11, %f25;
    ld.global.f32 %f25, [%rd2+48];
    add.f32 %f12, %f12, %f25;
    ld.global.f32 %f25, [%rd2+52];
    add.f32 %f13, %f13, %f25;
    ld.global.f32 %f25, [%rd2+56];
    add.f32 %f14, %f14, %f25;
    ld.global.f32 %f25, [%rd2+60];
    add.f32 %f15, %f15, %f25;
    ld.global.f32 %f25, [%rd2+64];
    add.f32 %f16, %f16, %f25;
    ld.global.f32 %f25, [%rd2+68];
    add.f32 %f17, %f17, %f25;
    ld.global.f32 %f25, [%rd2+72];
    add.f32 %f18, %f18, %f25;
    ld.global.f32 %f25, [%rd2+76];
    add.f32 %f19, %f19, %f25;
    ld.global.f32 %f25, [%rd2+80];
    add.f32 %f20, %f20, %f25;
    ld.global.f32 %f25, [%rd2+84];
    add.f32 %f21, %f21, %f25;
    ld.global.f32 %f25, [%rd2+88];
    add.f32 %f22, %f22, %f25;
    ld.global.f32 %f25, [%rd2+92];
    add.f32 %f23, %f23, %f25;
STORE:
    // sp(r33) = spatial offset inside the batch = row*98 + x - b*941192
    mul.lo.u32 %r33, %r5, 98;
    add.u32 %r33, %r33, %r14;
    mul.lo.u32 %r34, %r10, 941192;
    sub.u32 %r33, %r33, %r34;
    // rd17 = out + (b*24*941192 + sp) * 4 ; oc plane stride = 941192*4 = 3764768 B
    mad.lo.u32 %r34, %r10, 22588608, %r33;
    mul.wide.u32 %rd16, %r34, 4;
    add.s64 %rd17, %rd3, %rd16;
    st.global.f32 [%rd17], %f0;
    st.global.f32 [%rd17+3764768], %f1;
    st.global.f32 [%rd17+7529536], %f2;
    st.global.f32 [%rd17+11294304], %f3;
    st.global.f32 [%rd17+15059072], %f4;
    st.global.f32 [%rd17+18823840], %f5;
    st.global.f32 [%rd17+22588608], %f6;
    st.global.f32 [%rd17+26353376], %f7;
    st.global.f32 [%rd17+30118144], %f8;
    st.global.f32 [%rd17+33882912], %f9;
    st.global.f32 [%rd17+37647680], %f10;
    st.global.f32 [%rd17+41412448], %f11;
    st.global.f32 [%rd17+45177216], %f12;
    st.global.f32 [%rd17+48941984], %f13;
